div.script:

const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const heightVal = document.getElementById('heightVal');
const bestVal = document.getElementById('bestVal');

let highScore = parseInt(localStorage.getItem('tte_high') || '0', 10);
bestVal.textContent = highScore;

// Player state
let player = {
  x: 240,
  y: 450,
  w: 36,
  h: 36,
  vx: 0,
  vy: 0,
  speed: 6,
  gravity: 0.35,
  jumpStrength: -11
};

let platforms = [];
let cameraY = 0;
let maxScore = 0;
let isGameOver = false;

let keys = { left: false, right: false };

window.addEventListener('keydown', (e) => {
  if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = true;
  if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = true;
});

window.addEventListener('keyup', (e) => {
  if (e.code === 'ArrowLeft' || e.code === 'KeyA') keys.left = false;
  if (e.code === 'ArrowRight' || e.code === 'KeyD') keys.right = false;
});

function initPlatforms() {
  platforms = [
    { x: 200, y: 520, w: 90, h: 16, type: 'normal' },
    { x: 100, y: 420, w: 80, h: 16, type: 'normal' },
    { x: 300, y: 320, w: 80, h: 16, type: 'normal' },
    { x: 150, y: 220, w: 80, h: 16, type: 'normal' },
    { x: 250, y: 120, w: 80, h: 16, type: 'normal' },
    { x: 120, y: 20, w: 80, h: 16, type: 'normal' }
  ];
}

function resetGame() {
  player.x = 240;
  player.y = 450;
  player.vx = 0;
  player.vy = 0;
  cameraY = 0;
  maxScore = 0;
  isGameOver = false;
  initPlatforms();
  loop();
}

function update() {
  if (isGameOver) return;

  // Input movement
  if (keys.left) player.vx = -player.speed;
  else if (keys.right) player.vx = player.speed;
  else player.vx *= 0.8;

  player.x += player.vx;

  // Screen wrap
  if (player.x < -player.w) player.x = canvas.width;
  if (player.x > canvas.width) player.x = -player.w;

  // Gravity & physics
  player.vy += player.gravity;
  player.y += player.vy;

  // Platform collisions (only when falling)
  if (player.vy > 0) {
    platforms.forEach(p => {
      if (
        player.x + player.w > p.x &&
        player.x < p.x + p.w &&
        player.y + player.h >= p.y &&
        player.y + player.h <= p.y + p.h + player.vy
      ) {
        player.vy = player.jumpStrength;
      }
    });
  }

  // Camera follow upwards
  if (player.y < cameraY + 250) {
    let diff = (cameraY + 250) - player.y;
    cameraY -= diff;
    let currentHeight = Math.floor(-cameraY / 10);
    if (currentHeight > maxScore) {
      maxScore = currentHeight;
      heightVal.textContent = maxScore;
      if (maxScore > highScore) {
        highScore = maxScore;
        localStorage.setItem('tte_high', highScore.toString());
        bestVal.textContent = highScore;
      }
    }
  }

  // Generate platforms dynamically above
  let highestPlatformY = Math.min(...platforms.map(p => p.y));
  if (highestPlatformY > cameraY - 50) {
    platforms.push({
      x: Math.random() * (canvas.width - 90),
      y: highestPlatformY - (70 + Math.random() * 40),
      w: 75 + Math.random() * 20,
      h: 16,
      type: 'normal'
    });
  }

  // Remove platforms far below camera
  platforms = platforms.filter(p => p.y < cameraY + canvas.height + 100);

  // Game over condition (falling below screen)
  if (player.y > cameraY + canvas.height + 50) {
    isGameOver = true;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.save();
  ctx.translate(0, -cameraY);

  // Draw Platforms
  platforms.forEach(p => {
    ctx.fillStyle = '#38bdf8';
    ctx.strokeStyle = '#0284c7';
    ctx.lineWidth = 2;
    ctx.fillRect(p.x, p.y, p.w, p.h);
    ctx.strokeRect(p.x, p.y, p.w, p.h);
  });

  // Draw Player (Eagle Character)
  ctx.fillStyle = '#f59e0b';
  ctx.strokeStyle = '#d97706';
  ctx.lineWidth = 2;
  ctx.fillRect(player.x, player.y, player.w, player.h);
  ctx.strokeRect(player.x, player.y, player.w, player.h);

  // Simple Eagle Eyes / Beak details
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(player.x + 20, player.y + 8, 8, 8);
  ctx.fillStyle = '#0f172a';
  ctx.fillRect(player.x + 24, player.y + 10, 4, 4);

  ctx.fillStyle = '#ea580c'; // Beak
  ctx.beginPath();
  ctx.moveTo(player.x + player.w, player.y + 14);
  ctx.lineTo(player.x + player.w + 10, player.y + 18);
  ctx.lineTo(player.x + player.w, player.y + 22);
  ctx.closePath();
  ctx.fill();

  ctx.restore();

  // Game Over Overlay
  if (isGameOver) {
    ctx.fillStyle = 'rgba(11, 15, 25, 0.85)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = '#f8fafc';
    ctx.font = '900 36px system-ui';
    ctx.textAlign = 'center';
    ctx.fillText('FELL DOWN!', canvas.width / 2, canvas.height / 2 - 20);

    ctx.fillStyle = '#94a3b8';
    ctx.font = '700 18px system-ui';
    ctx.fillText('Click anywhere to Retry', canvas.width / 2, canvas.height / 2 + 25);
  }
}

canvas.addEventListener('click', () => {
  if (isGameOver) {
    resetGame();
  }
});

function loop() {
  update();
  draw();
  if (!isGameOver) {
    requestAnimationFrame(loop);
  }
}

initPlatforms();
loop();
